REVOKE EXECUTE ON FUNCTION lth_pvr.get_annual_fee_accruals__core(p_accrual_year integer) FROM public, anon, authenticated;
CREATE FUNCTION lth_pvr.get_annual_fee_accruals(p_accrual_year integer DEFAULT NULL::integer)
 RETURNS TABLE(accrual_id uuid, customer_id bigint, first_name text, last_name text, accrual_year integer, period_start date, period_end date, accrued_platform_fee_btc numeric, accrued_platform_fee_usdt numeric, accrued_performance_fee_usdt numeric, performance_fee_calculated_at timestamp with time zone, settled_at timestamp with time zone, settlement_notes text, updated_at timestamp with time zone)
 LANGUAGE plpgsql
